import {jiraStory} from './jira-core.js';
import {blankWorkspace,validateWorkspace,changeStory,elapsed,reportText} from './testing-core.js';
const $=id=>document.getElementById(id),key='rr-testing-workspace-v1';let w=blankWorkspace(),storyId='',sessionId='',pending=null,handoff='';
const status=s=>$('work-status').textContent=s;
try{const stored=localStorage.getItem(key);if(stored)w=validateWorkspace(JSON.parse(stored));}catch{status('Saved workspace could not be read. Export or recover it before replacing it.');}
try{const saved=sessionStorage.getItem('rr-testing-handoff');if(saved){const data=JSON.parse(saved);if(typeof data.summary==='string'&&data.summary.length<2000)handoff=data.summary;}}catch{}
const story=()=>w.stories.find(s=>s.id===storyId),session=()=>w.sessions.find(s=>s.id===sessionId);
function snapshot(){const copy=structuredClone(w);for(const s of copy.sessions){s.elapsedMs=elapsed(s);s.runningSince=0;if(s.state==='Running')s.state='Paused';}return copy;}
function persist(){try{localStorage.setItem(key,JSON.stringify(snapshot()));}catch{status('Browser storage is unavailable or full. Export your workspace to keep it.');}}
function download(name,data,type){const u=URL.createObjectURL(new Blob([data],{type})),a=document.createElement('a');a.href=u;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(u),1000);}
function board(){const host=$('story-board');host.replaceChildren();for(const s of w.stories){const b=document.createElement('button');b.type='button';b.setAttribute('aria-pressed',String(s.id===storyId));const name=document.createElement('span');name.textContent=s.title;const state=document.createElement('small');state.textContent=`${s.status} · ${s.priority}`;b.append(name,state);b.onclick=()=>{storyId=s.id;sessionId='';renderStory();board();};host.append(b);}$('work-summary').textContent=`${w.stories.length} stories · ${w.sessions.length} sessions`;}
function renderStory(){const s=story();for(const [id,k]of [['story-title','title'],['story-criteria','criteria'],['story-examples','examples'],['story-risks','risks'],['story-questions','questions'],['story-reviewer','reviewer'],['story-decision','decision']])$(id).value=s?.[k]||'';$('story-priority').value=s?.priority||'High';$('story-state').value=s?.status||'Planned';renderSessions();}
function renderSessions(){const select=$('session-list');select.replaceChildren(new Option('New session',''));for(const s of w.sessions.filter(s=>s.storyId===storyId))select.append(new Option(`${s.charter.slice(0,65)} · ${s.state}`,s.id));select.value=sessionId;renderSession();}
function renderSession(){const s=session();for(const [id,k]of [['session-charter','charter'],['session-oracle','oracle'],['session-coverage','coverage'],['session-debrief','debrief'],['session-next','next']])$(id).value=s?.[k]||'';$('session-minutes').value=s?.timebox||25;$('session-notes').replaceChildren();for(const n of s?.notes||[]){const d=document.createElement('div');d.className='discovery';const title=document.createElement('strong');title.textContent=n.kind;const date=document.createElement('small');date.textContent=n.at;const p=document.createElement('p');p.textContent=n.text;d.append(title,date,p);$('session-notes').append(d);}$('revision-note').textContent=s?`Session tied to story revision ${s.revision}.${s.revision!==story()?.revision?' The story has changed. Review this evidence and create a new charter if needed.':''}`:'Select or create a story before saving a charter.';timer();renderHandoff();}
function timer(){const s=session();const seconds=Math.floor(s?elapsed(s)/1000:0);$('session-timer').textContent=`${Math.floor(seconds/60).toString().padStart(2,'0')}:${(seconds%60).toString().padStart(2,'0')}`;$('session-state').textContent=s?`${s.state}${seconds>=s.timebox*60?' · timebox reached; adapt or continue':''}`:'No session selected';$('start-session').disabled=!s||['Running','Ended'].includes(s.state);$('pause-session').disabled=s?.state!=='Running';$('end-session').disabled=!s||s.state==='Ended';}
function renderHandoff(){$('api-handoff').hidden=!handoff;$('api-handoff-text').textContent=handoff;$('attach-api').disabled=!session();}
function all(){for(const [id,k]of [['sprint-name','name'],['sprint-goal','goal'],['sprint-done','done'],['sprint-retro','retro']])$(id).value=w.sprint[k];board();renderStory();renderHandoff();}
const guard=fn=>async e=>{e?.preventDefault();try{await fn();}catch(error){status(error.message);}};
$('save-sprint').onclick=()=>{const changed=w.sprint.goal!==$('sprint-goal').value||w.sprint.done!==$('sprint-done').value;w.sprint.name=$('sprint-name').value;w.sprint.goal=$('sprint-goal').value;w.sprint.done=$('sprint-done').value;if(changed)for(const s of w.stories)if(s.status==='Done'){s.status='Review';s.reviewer='';s.decision='';}persist();board();renderStory();status(changed?'Context saved. Previously done stories need a fresh review.':'Context saved.');};
$('save-retro').onclick=()=>{w.sprint.retro=$('sprint-retro').value;persist();status('Retrospective saved. Bring the experiment into the next planning discussion.');};
$('new-story').onclick=()=>{storyId='';sessionId='';renderStory();board();$('story-title').focus();};
$('story-form').onsubmit=guard(()=>{const values={title:$('story-title').value.trim(),priority:$('story-priority').value,status:$('story-state').value,criteria:$('story-criteria').value,risks:$('story-risks').value,examples:$('story-examples').value,questions:$('story-questions').value,reviewer:$('story-reviewer').value.trim(),decision:$('story-decision').value.trim()};if(!values.title)throw Error('Add a user need or story title.');if(values.status==='Done'&&(!values.reviewer||!values.decision))throw Error('Record a reviewer and decision rationale before marking Done.');const old=story();let next;if(old){next=changeStory(old,values);w.stories[w.stories.indexOf(old)]=next;}else{if(w.stories.length>=100)throw Error('Workspace limit: 100 stories. Export and start a new workspace.');next={id:crypto.randomUUID(),revision:1,...values};w.stories.push(next);storyId=next.id;}persist();board();renderStory();status(next.revision!==old?.revision&&old?'Story revised. Earlier sessions retain their original revision and review needs updating.':'Story saved. Discuss assumptions before starting the next investigation.');});
$('session-form').onsubmit=guard(()=>{if(!story())throw Error('Save or select a story first.');const charter=$('session-charter').value.trim(),timebox=Number($('session-minutes').value);if(!charter||!Number.isFinite(timebox)||timebox<1||timebox>180)throw Error('Add a charter and a 1–180 minute timebox.');let s=session();if(s?.state==='Ended')throw Error('An ended charter is retained as evidence. Choose New session to explore further.');if(!s){if(w.sessions.length>=300)throw Error('Workspace limit: 300 sessions.');s={id:crypto.randomUUID(),storyId,revision:story().revision,notes:[],elapsedMs:0,runningSince:0,state:'Ready',debrief:'',next:''};w.sessions.push(s);sessionId=s.id;}Object.assign(s,{charter,timebox,oracle:$('session-oracle').value,coverage:$('session-coverage').value});persist();board();renderSessions();status('Charter saved. Adapt the investigation as you learn.');});
$('session-list').onchange=()=>{sessionId=$('session-list').value;renderSession();};
function stop(s,state){s.elapsedMs=elapsed(s);s.runningSince=0;s.state=state;}
$('start-session').onclick=()=>{const s=session();if(!s||s.state==='Ended')return;for(const other of w.sessions)if(other.state==='Running')stop(other,'Paused');s.state='Running';s.runningSince=Date.now();persist();timer();status('Session started. Other running sessions were paused. Record discoveries, not just pass/fail results.');};
$('pause-session').onclick=()=>{if(session())stop(session(),'Paused');persist();timer();};$('end-session').onclick=()=>{if(session())stop(session(),'Ended');persist();renderSessions();status('Session ended. Add a debrief: learning, coverage gaps, blockers and next actions.');};
function note(kind,text){const s=session();if(!s)throw Error('Save or select a session first.');if(!text.trim())throw Error('Describe your discovery.');if(s.notes.length>=500)throw Error('Session note limit reached. Start a follow-up session.');s.notes.push({kind,text:text.trim(),at:new Date().toISOString()});persist();renderSession();}
$('note-form').onsubmit=guard(()=>{note($('note-kind').value,$('note-text').value);$('note-text').value='';status('Discovery recorded. Bug candidates still need investigation and team triage.');});
$('save-debrief').onclick=guard(()=>{const s=session();if(!s)throw Error('Save or select a session first.');s.debrief=$('session-debrief').value;s.next=$('session-next').value;persist();status('Debrief saved. Use the learning to update priorities and the next charter.');});
$('attach-api').onclick=guard(()=>{if(!handoff)return;note('Automated check',handoff);handoff='';sessionStorage.removeItem('rr-testing-handoff');renderHandoff();status('API check summary attached. This is evidence for specific checks, not complete test coverage.');});
$('discard-api').onclick=()=>{handoff='';sessionStorage.removeItem('rr-testing-handoff');renderHandoff();};
$('export-work').onclick=()=>download('releaseradar-testing-workspace.json',JSON.stringify(snapshot(),null,2),'application/json');$('export-story').onclick=()=>download('releaseradar-testing-report.md',reportText(snapshot()),'text/markdown');
$('import-work').onchange=guard(async()=>{const file=$('import-work').files[0];if(!file)return;if(file.size>2000000)throw Error('Workspace import limit is 2 MB.');pending=validateWorkspace(JSON.parse(await file.text()));$('import-description').textContent=`Replace this browser workspace with ${pending.stories.length} stories and ${pending.sessions.length} sessions from “${pending.sprint.name}”? Export existing work first.`;$('pending-import').hidden=false;$('import-work').value='';});
$('confirm-import').onclick=()=>{if(!pending)return;w=pending;pending=null;storyId=w.stories[0]?.id||'';sessionId='';$('pending-import').hidden=true;persist();all();status('Workspace imported. Any previously running timers are paused.');};$('cancel-import').onclick=()=>{pending=null;$('pending-import').hidden=true;};
$('sample-work').onclick=guard(()=>{if(w.stories.length>=100)throw Error('Story capacity reached.');const s={id:crypto.randomUUID(),title:'Example: shipping after discounts',priority:'High',status:'Planned',revision:1,criteria:'Shipping is free only when subtotal after discounts is at least $100. Otherwise charge $10.',examples:'Given a $110 basket and $20 discount\nWhen shipping is calculated\nThen the shopper pays $10 shipping.',risks:'Incorrect discounts may cause overcharging or lost shipping revenue. Currency rounding and invalid discounts are uncertain.',questions:'Business: Does the threshold include tax?\nDevelopment: Where is rounding applied?\nTesting: What happens at $99.99 and $100.00?',reviewer:'',decision:''};w.stories.push(s);storyId=s.id;sessionId='';persist();all();$('session-charter').value='Explore discounted basket boundaries with varied amounts to discover incorrect shipping charges.';$('session-oracle').value='Compare against the agreed after-discount rule; clarify tax and rounding before judging those outcomes.';$('session-coverage').value='Just below / at / above threshold; zero, partial and full discounts; invalid input; rounding.';status('Illustrative story added. No testing has been executed and no evidence invented.');});
storyId=w.stories[0]?.id||'';all();setInterval(timer,1000);setInterval(()=>{if(w.sessions.some(s=>s.state==='Running'))persist();},5000);addEventListener('pagehide',persist);

export function jiraContext(){if(!story()||!session())throw Error('Select a story and session first.');return {story:structuredClone(story()),session:structuredClone(session()),sprint:structuredClone(w.sprint)};}
export function addJiraStories(issues,site,sprintId){let added=0,skipped=0;for(const issue of issues){if(w.stories.some(s=>s.jira?.site===site&&s.jira?.key===issue.key)){skipped++;continue;}if(w.stories.length>=100)break;w.stories.push(jiraStory(issue,site,sprintId));added++;}if(!storyId)storyId=w.stories[0]?.id||'';persist();all();status(added+' Jira issues imported; '+skipped+' duplicates skipped. Existing local edits were preserved.');return {added,skipped};}
export function addJiraReceipt(sessionKey,result){const target=w.sessions.find(s=>s.id===sessionKey);if(!target)return;if(!target.notes.some(n=>n.text.includes(result.url))){target.notes.push({kind:'Observation',at:new Date().toISOString(),text:'Jira bug created: '+result.url+' · Evidence upload status: '+result.phase});}else{const n=target.notes.find(n=>n.text.includes(result.url));n.text='Jira bug created: '+result.url+' · Evidence upload status: '+result.phase;}persist();renderSession();}
